public static str metTotalQuantity()
{
    str             transferId              = SysComputedColumn::returnField(tablestr(METInventTransferOrderHeaderEntity), dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable), fieldStr(InventTransferTable, TransferId));

    return 'SELECT sum(QtyTransfer) FROM InventTransferLine WHERE TransferId = ' + transferId;

}

public static str metTotalWeight()
{
    str             transferId              = SysComputedColumn::returnField(tablestr(METInventTransferOrderHeaderEntity), dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable), fieldStr(InventTransferTable, TransferId));

    return 'select sum(TotalWeight) from METINVENTTRANSFERLINE MITL ' +
            ' join INVENTTRANSFERLINE ITL on ITL.RECID = MITL.INVENTTRANSFERLINE ' +
            ' where itl.TRANSFERID = ' + transferId;

}

public static str metTotalVolume()
{
    str             transferId              = SysComputedColumn::returnField(tablestr(METInventTransferOrderHeaderEntity), dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable), fieldStr(InventTransferTable, TransferId));

    return 'select sum(TotalVolume) from METINVENTTRANSFERLINE MITL ' +
            ' join INVENTTRANSFERLINE ITL on ITL.RECID = MITL.INVENTTRANSFERLINE ' +
            ' where itl.TRANSFERID = ' + transferId;

}

public static str metWarehouseEmail() { str toWarehouse = SysComputedColumn::returnField(tablestr(METInventTransferOrderHeaderEntity), dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable), fieldStr(InventTransferTable, InventLocationIdTo));
return 'select top 1 h.LOCATOR from INVENTLOCATION a ' + 'join InventLocationLogisticsLocation b ' + 'on b.INVENTLOCATION = a.RECID ' + 'join InventLocationLogisticsLocationRole c ' + 'on c.LOCATIONLOGISTICSLOCATION = b.RECID ' + 'join LogisticsLocationRole d ' + 'on d.RECID = c.LOCATIONROLE ' + 'join LOGISTICSLOCATION e ' + 'on e.RECID = b.LOCATION ' + 'join LOGISTICSPOSTALADDRESS f ' + 'on f.LOCATION = e.RECID ' + 'join LOGISTICSLOCATION g ' + 'on g.PARENTLOCATION = f.LOCATION ' + 'join LOGISTICSELECTRONICADDRESS h ' + 'on h.LOCATION = g.RECID ' + 'join LOGISTICSELECTRONICADDRESSROLE i ' + 'on i.ELECTRONICADDRESS = h.RECID ' + 'join LOGISTICSLOCATIONROLE j ' + 'on j.RECID = i.LOCATIONROLE ' + 'where b.ISPRIMARY = 1 ' + 'and d.TYPE = 2 ' + 'and h.TYPE = 2 ' + 'and h.ISPRIMARY = 1 ' + //'and j.NAME = ' + roleType + 'and a.INVENTLOCATIONID = ' + toWarehouse + ' order by f.VALIDTO desc ' ;
}
